output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are prohibited in one-cell-wide aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_between_facing_shelves",
    "text": "Customers must not push a cart through aisles flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "between_facing_shelves"
        ]
      }
    }
  },
  {
    "id": "park_before_foot_only_aisle",
    "text": "A customer may not enter a foot-only aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "foot_only_aisle": {
          "or": [
            "single_file_aisle",
            "between_facing_shelves"
          ]
        }
      },
      "events": {
        "enter_foot_only_aisle": {
          "pre": {
            "and": [
              {
                "not": "foot_only_aisle"
              },
              "MOVE"
            ]
          },
          "post": "foot_only_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enter_foot_only_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_item_access_in_foot_aisle",
    "text": "Shelf interactions inside foot-only aisles must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "foot_only_aisle": {
          "or": [
            "single_file_aisle",
            "between_facing_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "foot_only_aisle"
        ]
      }
    }
  },
  {
    "id": "cart_abandon_only_at_staging",
    "text": "Carts may be set down only at the designated staging point outside the narrow upper aisle.",
    "abstraction": {
      "state_properties": {
        "wide_cross_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        },
        "cart_staging_area": {
          "and": [
            "at(6,3)",
            "wide_cross_aisle"
          ]
        }
      },
      "events": {
        "set_down_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "set_down_cart",
          {
            "not": "cart_staging_area"
          }
        ]
      }
    }
  },
  {
    "id": "no_roaming_without_cart",
    "text": "Customers should not roam in wide public aisles without a cart, except at the entrance/cart bay or the narrow-aisle staging point.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "foot_only_aisle": {
          "or": [
            "single_file_aisle",
            "between_facing_shelves"
          ]
        },
        "wide_public_aisle": {
          "not": "foot_only_aisle"
        },
        "cart_collection_zone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cart_staging_area": "at(6,3)",
        "cartless_exception_zone": {
          "or": [
            "cart_collection_zone",
            "cart_staging_area"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "wide_public_aisle",
          {
            "not": "cartless_exception_zone"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_after_emerging",
    "text": "After returning from a foot-only aisle without a cart, the customer must immediately reclaim a cart at the staging point before continuing.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "foot_only_aisle": {
          "or": [
            "single_file_aisle",
            "between_facing_shelves"
          ]
        },
        "wide_public_aisle": {
          "not": "foot_only_aisle"
        },
        "cart_staging_area": "at(6,3)"
      },
      "events": {
        "emerge_from_foot_only_without_cart": {
          "pre": {
            "and": [
              "foot_only_aisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "wide_public_aisle",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "reclaim_cart_at_staging": {
          "pre": {
            "and": [
              "cart_staging_area",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "emerge_from_foot_only_without_cart",
      "discharge": "reclaim_cart_at_staging"
    }
  },
  {
    "id": "return_to_staging_after_foot_only",
    "text": "A cartless visit into a foot-only aisle must end by returning to the staging point where the cart was left.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "foot_only_aisle": {
          "or": [
            "single_file_aisle",
            "between_facing_shelves"
          ]
        },
        "cart_staging_area": "at(6,3)"
      },
      "events": {
        "enter_foot_only_without_cart": {
          "pre": {
            "and": [
              {
                "not": "foot_only_aisle"
              },
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "foot_only_aisle",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "return_to_staging_without_cart": {
          "pre": {
            "and": [
              "foot_only_aisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "cart_staging_area",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_foot_only_without_cart",
      "discharge": "return_to_staging_without_cart"
    }
  }
]
